window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1c7db911e53fb610"]={"versions": [{"id": "FIG-1c7db911e53fb610", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenmodell der AUTOSAR-Classic-Gesamtarchitektur („Overall layered architecture“). Das Blockschaltbild visualisiert die hierarchische Strukturierung eines AUTOSAR-Steuergerätesozietäts-Knotens von der Applikation bis zur physischen Hardware sowie vertikale Pfade und Sonderstrukturen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Software- und Hardwarearchitektur gliedert sich in folgende Hauptebenen und Entitäten:</p>\n<ul class=\"fig-list\">\n<li><strong>Application Layer</strong>: Oberste Softwareebene zur Ausführung von Software-Components (SWCs).</li>\n<li><strong>AUTOSAR Runtime Environment (RTE)</strong>: Zwischenschicht, die die Kommunikation zwischen Applikationskomponenten untereinander sowie zwischen Applikationskomponenten und Basissoftware (BSW) abstrahiert.</li>\n<li><strong>Basis Software (BSW)</strong>, bestehend aus:</li>\n<li><strong>Services Layer</strong>: Oberste Schicht der BSW; stellt systemweite Basisfunktionen wie Speicherverwaltung, Netzwerkmanagement, Diagnose und Betriebssystem bereit. Eine seitliche Ausformung reicht bis auf Hardwareebene herunter (z. B. OS-Kern / Systemdienste).</li>\n<li><strong>ECU Abstraction Layer</strong>: Kapselt Peripherie und externe Geräte; stellt einheitliche Schnittstellen zur Hardware unabhängig von Controller-Pins bereit und greift teils direkt auf Hardware oder MCAL zu.</li>\n<li><strong>Microcontroller Abstraction Layer (MCAL)</strong>: Unterste Softwareschicht mit hardwarenahen Treibern zum direkten Zugriff auf interne Peripherie und Controller-Register.</li>\n<li><strong>Complex Drivers (CDD)</strong>: Schichtenübergreifender Block parallel zu den BSW-Schichten, der direkte Zugriffe von der RTE bis unmittelbar auf die Hardware ermöglicht (z. B. für zeitkritische oder nicht standardisierte Sensor-/Aktor-Treiber).</li>\n<li><strong>Hardware</strong>: Physische Ausführungsebene (Mikrocontroller und Peripherie) als Basis des Gesamtsystems.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schichtenübersicht ohne dynamische Ablauf- oder Signalpfade. Die geometrische Anordnung impliziert vertikale Interaktionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li>Regulärer Kontroll- und Datenfluss erfolgt hierarchisch von der Application Layer über die RTE durch Services Layer, ECU Abstraction Layer und MCAL bis zur Hardware.</li>\n<li>Der Services Layer verfügt über direkte Schnittstellenpfade bis auf Hardwareebene (unter Umgehung von ECU Abstraction Layer und MCAL).</li>\n<li>Der ECU Abstraction Layer kann über eigene Treiberpfade Peripherie ansteuern oder standardisierte MCAL-Treiber nutzen.</li>\n<li>Complex Drivers umgehen die standardisierten BSW-Schichten und bieten eine direkte Schnittstelle zwischen RTE und Hardware.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Zentrale architektonische Referenz für das Schichtenkonzept der AUTOSAR Classic Platform. Entwickler von Steuergeräte-Software müssen die Schichtgrenzen und Entkopplungsmechanismen einhalten:</p>\n<ul class=\"fig-list\">\n<li>Applikationskomponenten dürfen ausschließlich über standardisierte RTE-Schnittstellen kommunizieren und besitzen keinen direkten BSW- oder Hardwarezugriff.</li>\n<li>BSW-Treiber müssen strikt der entsprechenden Abstraktionsebene zugeordnet werden, um Hardware-Portabilität zu gewährleisten.</li>\n<li>Complex Drivers sind restriktiv auf Anwendungsfälle mit extremen Latenzanforderungen oder proprietärer Hardware beschränkt, da sie die standardisierte Portabilität der Schichtenarchitektur aufbrechen.</li>\n</ul>"}, {"id": "FIG-f1a17714b0ff44ca", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenmodell der AUTOSAR-Classic-Gesamtarchitektur („Overall layered architecture“). Das Blockschaltbild visualisiert die hierarchische Strukturierung eines AUTOSAR-Steuergerätesozietäts-Knotens von der Applikation bis zur physischen Hardware sowie vertikale Pfade und Sonderstrukturen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Software- und Hardwarearchitektur gliedert sich in folgende Hauptebenen und Entitäten:</p>\n<ul class=\"fig-list\">\n<li><strong>Application Layer</strong>: Oberste Softwareebene zur Ausführung von Software-Components (SWCs).</li>\n<li><strong>AUTOSAR Runtime Environment (RTE)</strong>: Zwischenschicht, die die Kommunikation zwischen Applikationskomponenten untereinander sowie zwischen Applikationskomponenten und Basissoftware (BSW) abstrahiert.</li>\n<li><strong>Basis Software (BSW)</strong>, bestehend aus:</li>\n<li><strong>Services Layer</strong>: Oberste Schicht der BSW; stellt systemweite Basisfunktionen wie Speicherverwaltung, Netzwerkmanagement, Diagnose und Betriebssystem bereit. Eine seitliche Ausformung reicht bis auf Hardwareebene herunter (z. B. OS-Kern / Systemdienste).</li>\n<li><strong>ECU Abstraction Layer</strong>: Kapselt Peripherie und externe Geräte; stellt einheitliche Schnittstellen zur Hardware unabhängig von Controller-Pins bereit und greift teils direkt auf Hardware oder MCAL zu.</li>\n<li><strong>Microcontroller Abstraction Layer (MCAL)</strong>: Unterste Softwareschicht mit hardwarenahen Treibern zum direkten Zugriff auf interne Peripherie und Controller-Register.</li>\n<li><strong>Complex Drivers (CDD)</strong>: Schichtenübergreifender Block parallel zu den BSW-Schichten, der direkte Zugriffe von der RTE bis unmittelbar auf die Hardware ermöglicht (z. B. für zeitkritische oder nicht standardisierte Sensor-/Aktor-Treiber).</li>\n<li><strong>Hardware</strong>: Physische Ausführungsebene (Mikrocontroller und Peripherie) als Basis des Gesamtsystems.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schichtenübersicht ohne dynamische Ablauf- oder Signalpfade. Die geometrische Anordnung impliziert vertikale Interaktionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li>Regulärer Kontroll- und Datenfluss erfolgt hierarchisch von der Application Layer über die RTE durch Services Layer, ECU Abstraction Layer und MCAL bis zur Hardware.</li>\n<li>Der Services Layer verfügt über direkte Schnittstellenpfade bis auf Hardwareebene (unter Umgehung von ECU Abstraction Layer und MCAL).</li>\n<li>Der ECU Abstraction Layer kann über eigene Treiberpfade Peripherie ansteuern oder standardisierte MCAL-Treiber nutzen.</li>\n<li>Complex Drivers umgehen die standardisierten BSW-Schichten und bieten eine direkte Schnittstelle zwischen RTE und Hardware.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Zentrale architektonische Referenz für das Schichtenkonzept der AUTOSAR Classic Platform. Entwickler von Steuergeräte-Software müssen die Schichtgrenzen und Entkopplungsmechanismen einhalten:</p>\n<ul class=\"fig-list\">\n<li>Applikationskomponenten dürfen ausschließlich über standardisierte RTE-Schnittstellen kommunizieren und besitzen keinen direkten BSW- oder Hardwarezugriff.</li>\n<li>BSW-Treiber müssen strikt der entsprechenden Abstraktionsebene zugeordnet werden, um Hardware-Portabilität zu gewährleisten.</li>\n<li>Complex Drivers sind restriktiv auf Anwendungsfälle mit extremen Latenzanforderungen oder proprietärer Hardware beschränkt, da sie die standardisierte Portabilität der Schichtenarchitektur aufbrechen.</li>\n</ul>"}], "trans": [{"from": "FIG-1c7db911e53fb610", "to": "FIG-f1a17714b0ff44ca", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
